            </div>
          </section>

          <!-- STEP 2 — Applies when -->
          <section class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 2</span>
              <span class="rb-step-title">{{ $t('applies_when') }}</span>
              <span class="rb-step-hint">{{ $t('leave_empty_to_match_every_document') }}</span>
            </div>
            <div class="sr-when">
