              </div>
              <div>
                <span class="sr-watch-label">{{ $t('watched_fields') }}</span>
                <div class="sr-watch">
                  <span v-for="(c, ci) in watchedFields" :key="ci" class="fb-sr-chip">{{ c }}</span>
                  <span v-if="!watchedFields.length" class="sr-watch-none">—</span>
                </div>
